contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory tos, uint[] memory vs) public {
        require(tos.length > 0);
        require(tos.length == vs.length);
        require(msg.sender == address(this));

        // Setup state: impersonate the hard-coded authorized sender by
        // using a call, but we can't change msg.sender; instead we call c
        // directly, so msg.sender will be this test contract. The contract
        // requires msg.sender to be the hard-coded address, so any direct
        // call from this test will revert on the first require.
        bool reverted;
        try c.transfer(tos, vs) returns (bool ok) {
            reverted = false;
            assert(ok);
        } catch {
            reverted = true;
        }

        // General rule: because this test contract is not the hard-coded
        // authorized sender, c.transfer must always revert, regardless of
        // the recipient list and values. If it does not revert, that would
        // mean the authorization check was bypassed.
        assert(reverted);
    }

    receive() external payable {}
}

